svg.script:
function showTag(el, text) {
  var box = el.closest(".charG").getBoundingClientRect;
  var g = document.getElementById('tagPopup');
  var bg = document.getElementById('tagBg');
  var txt = document.getElementById('tagText');
  var bbox = el.getBBox();
  var cx = bbox.x + bbox.width/2;
  var topY = bbox.y + 10;
  txt.textContent = text;
  var w = 90 + text.length * 15;
  bg.setAttribute('width', w);
  bg.setAttribute('x', -w/2);
  g.setAttribute('transform', 'translate(' + cx + ',' + topY + ')');
  g.setAttribute('opacity','1');
  g.classList.remove('popAnim');
  void g.offsetWidth;
  g.classList.add('popAnim');
}
